pub fn fn_body_is_target(body: &syn_verus::Block)-> bool {
    !body.to_token_stream().to_string().contains("unimplemented ! ()")
}

pub fn is_proof_or_exec(sig: &syn_verus::Signature) -> bool {
    match sig.mode {
        syn_verus::FnMode::Proof(_) | syn_verus::FnMode::Exec(_) | syn_verus::FnMode::Default => true,
        syn_verus::FnMode::Spec(_) | syn_verus::FnMode::SpecChecked(_)  | syn_verus::FnMode::ProofAxiom(_) => false,
    }
}

#[derive(Debug)]
pub enum Error {
    //IncorrectUsage,
    ReadFile(io::Error),
    ParseTokens { error: String, filepath: PathBuf },
    ParseFile { error: syn_verus::Error, filepath: PathBuf, source_code: String },
    NotFound(String),
    Conflict(String),
    WriteFile(io::Error)
}

impl Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        use self::Error::*;

        match self {
            //IncorrectUsage => write!(f, "Usage: dump-syntax path/to/filename.rs"),
            ReadFile(error) => write!(f, "Unable to read file: {}", error),
            ParseTokens { error, filepath } => {
                write!(f, "Unable to tokenize {}: {}", filepath.display(), error)
                        block: new_block,
                        semi_token: func.semi_token.clone(),
                    }
                },
                None => {
                    syn_verus::ImplItemFn {
                        attrs: remove_proof_attr(&func.attrs),
                        vis: func.vis.clone(),
                        defaultness: func.defaultness.clone(),
                        sig: remove_ghost_sig(&func.sig, &DeghostMode::default()).expect("exec fn has non-ghost sig"),
                        block: syn_verus::Block { brace_token: func.block.brace_token.clone(), stmts: Vec::new() }, // empty block
                        semi_token: func.semi_token.clone(),
                    }
                }
            }
        },
        Spec(_) | SpecChecked(_) | Proof(_) | ProofAxiom(_) => {
            func.clone()
        },
    }
}

fn remove_ghost_from_trait_exec_fn(func: &syn_verus::TraitItemFn) -> syn_verus::TraitItemFn {
    match func.sig.mode {
        Exec(_) | Default => {
            if func.default.is_some() {
                match remove_ghost_block(&(func.default.clone().unwrap()), &DeghostMode::default()) {
                    Some(new_block) => {
                        syn_verus::TraitItemFn {
                            attrs: remove_proof_attr(&func.attrs),
                            sig: remove_ghost_sig(&func.sig, &DeghostMode::default()).expect("exec fn has non-ghost sig"),
                            default: Some(new_block),
                            semi_token: func.semi_token.clone(),
                        }
                    },
                    None => {
                        syn_verus::TraitItemFn {
                            attrs: remove_proof_attr(&func.attrs),
                            sig: remove_ghost_sig(&func.sig, &DeghostMode::default()).expect("exec fn has non-ghost sig"),
                            default: None, // empty block
                            semi_token: func.semi_token.clone(),
                        }
                    }
                }
            } else {
                syn_verus::TraitItemFn {
                    attrs: remove_proof_attr(&func.attrs),
                    sig: remove_ghost_sig(&func.sig, &DeghostMode::default()).expect("exec fn has non-ghost sig"),
                    default: None, // empty block
                    semi_token: func.semi_token.clone(),
                }
            }
        },
        Spec(_) | SpecChecked(_) | Proof(_) | ProofAxiom(_) => {
            func.clone()
        },
    }
}

